// Disclaimer Text is versioned with the tax parameter set (ADR-0002), so it tracks the law year; es-MX, safe to show, never an amount. Order in a response: `not_tax_advice` first, then by severity (`strong`, `warning`, `info`), then by code.
//
// Examples: {"code":"not_tax_advice","severity":"info","text":"Estimación informativa. No sustituye la declaración ante el SAT ni la asesoría de un contador. Cálculo basado en LISR, LIVA, LIF 2026 y Anexo 8 RMF 2026."}
type Disclaimer struct {
	// Code Append-only (like `ErrorCode`): clients show the `text` of a code they do not know. `not_tax_advice` always; `incomplete_inputs` when a regime is `incomplete`; `provisional_parameters` when the period's fiscal year has no published parameters yet; `informational_regime` / `partial_regime` when a regime has that status; `deductibility_claimed` when a deductible expense entered the ISR base; `no_coefficient_first_year` for a 601 in its first fiscal year; `iva_mixed_activity` when a regime's creditable IVA was taken in full although it has exempt acts (`iva_fully_taxable = false`, or exempt collections in the month; LIVA 5 fr. V); `cpa_review_pending` when a line applies a rule a CPA has not validated (MODULE-tax-engine §2.3, §2.9).
	Code DisclaimerCode `json:"code"`

	// Severity `strong` is the non-dismissible amber banner above the number (`cpa_review_pending`); `warning` and `info` are shown under the estimate.
	Severity DisclaimerSeverity `json:"severity"`
	Text     string             `json:"text"`
}

// DisclaimerCode Append-only (like `ErrorCode`): clients show the `text` of a code they do not know. `not_tax_advice` always; `incomplete_inputs` when a regime is `incomplete`; `provisional_parameters` when the period's fiscal year has no published parameters yet; `informational_regime` / `partial_regime` when a regime has that status; `deductibility_claimed` when a deductible expense entered the ISR base; `no_coefficient_first_year` for a 601 in its first fiscal year; `iva_mixed_activity` when a regime's creditable IVA was taken in full although it has exempt acts (`iva_fully_taxable = false`, or exempt collections in the month; LIVA 5 fr. V); `cpa_review_pending` when a line applies a rule a CPA has not validated (MODULE-tax-engine §2.3, §2.9).
type DisclaimerCode string

// DisclaimerSeverity `strong` is the non-dismissible amber banner above the number (`cpa_review_pending`); `warning` and `info` are shown under the estimate.
type DisclaimerSeverity string

